+    [Fact]
+    public void Get_ConsumesValue_WhenFirstAccessTriggersLazyLoad()
+    {
+        var tempData = new TempData(() => new Dictionary<string, object>
+        {
+            ["Message"] = "hello"
+        });
+
+        var value = tempData.Get("Message");
