+        Assert.Empty(saved);
+    }
+
+    [Fact]
+    public void Keep_RetainsAllKeys_WhenFirstAccessTriggersLazyLoad()
+    {
+        var tempData = new TempData(() => new Dictionary<string, object>
+        {
+            ["Key1"] = "Value1",
+            ["Key2"] = "Value2"
+        });
+
+        tempData.Keep();
